={{ `You are a professional AI writer for LinkedIn-style posts.

POST TYPE: ${$json.postType || 'primary'}
TARGET TOPIC: ${$json.topic}

${($json.postType || '') === 'engage' ? `Write ONE short engagement post (poll-style question, quick tip, or thought-provoking question). 2-4 sentences max. No URLs.` : ($json.postType || '') === 'deep' ? `Write ONE deep technical post (architecture insight, system design lesson, or tutorial angle). 6-8 sentences with double line breaks. No URLs.` : `From the story catalog below, write 4 different draft posts (different stories/angles). Each draft should be unique.

Rules for each draft:
- No URLs in text (added automatically)
- 4-6 sentences, double line breaks, end with a question
- Professional tone, no hashtags/emojis/em dashes`}

Return ONLY valid JSON:
${($json.postType || '') === 'engage' || ($json.postType || '') === 'deep' ? '{\n  "headline": "...",\n  "message": "...",\n  "short_message": "...",\n  "story_index": 1\n}' : '{\n  "drafts": [\n    { "headline": "...", "message": "...", "short_message": "...", "story_index": 1, "score": 85 },\n    { "headline": "...", "message": "...", "short_message": "...", "story_index": 2, "score": 80 }\n  ]\n}'}

## Research briefing:
${$json.researchText || 'Use the target topic directly.'}` }}

=You are an expert visual prompt engineer for LinkedIn social posts.

Write ONE detailed image-generation prompt based on the post below. The image must be professional, modern, and visually compelling. Do not include any text, logos, watermarks, or UI chrome in the image.

Headline: {{ $json.headline }}

Post:
{{ $json.message }}

Return ONLY the image prompt text. No JSON, no markdown, no explanation.

parameters.jsCode:
function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

const selected = safeNode('Select Best Draft') || $input.first()?.json || {};
const research = safeNode('Format Research') || {};
const stories = research.stories || [];
const citations = research.citations || [];
const sourceUrlsFromText = research.sourceUrlsFromText || [];
const topicData = safeNode('Collect and Score Sources') || safeNode('Topic') || {};

const post = {
  headline: selected.headline || '',
  message: selected.message || '',
  short_message: selected.short_message || '',
  story_index: Number(selected.story_index) || 1,
};

function cleanUrl(url) { return (url || '').trim().replace(/[.,;:!?\)\]]+$/, ''); }
function isValidUrl(url) { return typeof url === 'string' && /^https?:\/\//i.test(cleanUrl(url)); }
function extractSourceUrls(blockText) {
  return [...blockText.matchAll(/^Source URL:\s*(https?:\/\/[^\s\)\]"'<>]+)/gim)].map((m) => cleanUrl(m[1]));
}
function splitStoryBlocks(blockText) {
  return blockText.replace(/\r/g, '').split(/(?:^|\n)---+(?:\n|$)/).map((b) => b.trim()).filter((b) => /STORY\s+\d+/i.test(b));
}
function urlForStoryIndex(storyIndex) {
  const story = stories.find((s) => s.index === storyIndex);
  if (story?.primaryUrl && isValidUrl(story.primaryUrl)) return story.primaryUrl;
  const blocks = splitStoryBlocks(research.researchText || '');
  const block = blocks.find((b) => new RegExp(`STORY\\s+${storyIndex}`, 'i').test(b)) || blocks[storyIndex - 1] || blocks[0];
  if (block) { const urls = extractSourceUrls(block); if (isValidUrl(urls[0])) return urls[0]; }
  const collected = safeNode('Collect and Score Sources')?.topStories || [];
  if (isValidUrl(collected[storyIndex - 1]?.link)) return collected[storyIndex - 1].link;
  for (const url of [citations[storyIndex - 1], citations[0], sourceUrlsFromText[storyIndex - 1], sourceUrlsFromText[0]]) {
    if (isValidUrl(url)) return url;
  }
  return '';
}
function stripUrls(input) {
  return (input || '').replace(/https?:\/\/[^\s\)\]"'<>]+/gi, '').replace(/\n{3,}/g, '\n\n').trim();
}
function attachSource(body, url) {
  const cleaned = stripUrls(body);
  const link = cleanUrl(url);
  if (!link || cleaned.includes(link)) return cleaned;
  return `${cleaned}\n\n${link}`;
}

const storyIndex = Number(post.story_index) || 1;
const primaryUrl = urlForStoryIndex(storyIndex);

return [{ json: {
  headline: post.headline || '',
  message: attachSource(post.message || post.short_message || '', primaryUrl),
  short_message: attachSource(post.short_message || post.message || '', primaryUrl),
  topic: selected.topic || research.topic || topicData.topic || '',
  postType: selected.postType || research.postType || topicData.postType || 'primary',
  pipelineSlot: selected.pipelineSlot || research.pipelineSlot || topicData.pipelineSlot || 'publish',
  publishNow: selected.publishNow ?? research.publishNow ?? topicData.publishNow ?? false,
  story_index: storyIndex,
  story_title: stories.find((s) => s.index === storyIndex)?.title || '',
  primaryUrl,
  citations,
} }];

function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

const channels = $('Postiz - Get Channels').all().map((item) => item.json);
const upload = safeNode('Postiz') || {};
const post = safeNode('Parse Post JSON') || safeNode('Load Primary Draft') || safeNode('Validate Draft') || safeNode('Mark Upload Failed') || {};

const limits = { threads: 500, bluesky: 300, linkedin: 3000, x: 280, twitter: 280, facebook: 63206, instagram: 2200 };

function contentForPlatform(platform) {
  const long = post.message || post.headline || post.short_message || '';
  const short = post.short_message || post.headline || long;
  const max = limits[platform];
  if (max && (platform === 'threads' || platform === 'bluesky' || platform === 'x' || platform === 'twitter')) {
    return short.length <= max ? short : `${short.slice(0, max - 3)}...`;
  }
  if (max && long.length > max) return `${long.slice(0, max - 3)}...`;
  return long;
}

function platformSettings(platform) {
  const settings = { __type: platform };
  if (platform === 'instagram' || platform === 'instagram-standalone') settings.post_type = 'post';
  if (platform === 'facebook') settings.post_type = 'post';
  return settings;
}

const imageAttachment = upload?.id && upload?.path ? [{ id: upload.id, path: upload.path }] : [];
const publishNow = post.publishNow === true;
const postType = post.postType || 'primary';

const posts = channels.filter((c) => !c.disabled).map((channel) => {
  const platform = channel.identifier || channel.platform;
  return {
    integration: { id: channel.id },
    value: [{ content: contentForPlatform(platform), id: '', image: imageAttachment }],
    group: '',
    settings: platformSettings(platform),
  };
});

return [{ json: {
  type: publishNow ? 'now' : 'draft',
  shortLink: false,
  date: new Date().toISOString(),
  tags: [{ value: postType }],
  posts,
  channelCount: posts.length,
  postType,
  publishNow,
  mediaUploadFailed: post.mediaUploadFailed === true,
} }];

function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

const upstream = $input.first().json;
const collected = safeNode('Collect and Score Sources');
const topicData = safeNode('Topic');

const topic = collected?.topic || topicData?.topic || upstream.topic || 'Breaking Tech News';
const postType = collected?.postType || topicData?.postType || upstream.postType || 'primary';
const pipelineSlot = collected?.pipelineSlot || topicData?.pipelineSlot || upstream.pipelineSlot || 'publish';
const publishNow = collected?.publishNow ?? topicData?.publishNow ?? upstream.publishNow ?? false;

let researchText = '';
if (typeof upstream.message === 'string') researchText = upstream.message;
else if (typeof upstream.content === 'string') researchText = upstream.content;
else researchText = JSON.stringify(upstream, null, 2);
researchText = researchText.replace(/\r/g, '');

const rawCitations = Array.isArray(upstream.citations)
  ? upstream.citations.filter((url) => typeof url === 'string' && /^https?:\/\//i.test(url))
  : [];

function cleanUrl(url) { return (url || '').trim().replace(/[.,;:!?\)\]]+$/, ''); }
function urlScore(url) {
  try {
    const pathParts = new URL(url).pathname.split('/').filter(Boolean);
    if (/youtube\.com|youtu\.be|vimeo\.com/i.test(url)) return 100;
    if (pathParts.length >= 3) return 85;
    if (pathParts.length >= 1) return 55;
    return 5;
  } catch { return 0; }
}
function isArticleUrl(url) { return urlScore(cleanUrl(url)) >= 50; }
function pickPrimaryUrl(urls) {
  const unique = [...new Set(urls.map(cleanUrl).filter(Boolean))];
  return unique.sort((a, b) => urlScore(b) - urlScore(a)).find(isArticleUrl) || unique[0] || '';
}
function extractUrls(text) { return (text.match(/https?:\/\/[^\s\)\]"'<>]+/gi) || []).map(cleanUrl); }
function extractSourceUrls(text) {
  return [...new Set([...text.matchAll(/^Source URL:\s*(.+)$/gim)].flatMap((m) => extractUrls(m[1])))];
}
function splitStoryBlocks(text) {
  return text.split(/(?:^|\n)---+(?:\n|$)/).map((b) => b.replace(/^---+\s*/m, '').trim()).filter((b) => /STORY\s+\d+/i.test(b));
}
function resolveCitationRefs(text, citationList) {
  return text.replace(/Source URL:\s*\[(\d+)\]/gi, (_, n) => {
    const url = citationList[Number(n) - 1] || citationList[Number(n)] || citationList[0];
    return url && /^https?:\/\//i.test(url) ? `Source URL: ${url}` : `Source URL: ${url || `[${n}]`}`;
  });
}

researchText = resolveCitationRefs(researchText, rawCitations);
const sourceUrlsFromText = extractSourceUrls(researchText);
const citations = [...new Set([...sourceUrlsFromText.filter(isArticleUrl), ...rawCitations.filter(isArticleUrl)])];
let storyBlocks = splitStoryBlocks(researchText);
if (!storyBlocks.length && citations.length) {
  storyBlocks = citations.map((url, i) => `### STORY ${i + 1}\nTitle: Story ${i + 1}\nSource URL: ${url}`);
}

const stories = storyBlocks.map((block, index) => {
  const storyIndex = Number((block.match(/STORY\s+(\d+)/i) || [])[1]) || index + 1;
  const titleMatch = block.match(/Title:\s*(.+)/i);
  const title = (titleMatch?.[1] || `Story ${storyIndex}`).replace(/^\*+|\*+$/g, '').trim();
  const blockUrls = [...extractSourceUrls(block), ...extractUrls(block)];
  const fallbackUrls = blockUrls.length ? blockUrls : [citations[storyIndex - 1], citations[index], citations[0]].filter(Boolean);
  return { index: storyIndex, title, primaryUrl: pickPrimaryUrl(fallbackUrls), sourceUrls: blockUrls.filter(isArticleUrl) };
}).filter((s) => s.primaryUrl).sort((a, b) => a.index - b.index);

const storyCatalog = stories.length
  ? stories.map((s) => `${s.index}. ${s.title}\n   Source: ${s.primaryUrl}`).join('\n')
  : citations.map((url, i) => `${i + 1}. Source: ${url}`).join('\n');

return [{ json: { topic, postType, pipelineSlot, publishNow, stories, citations, sourceUrlsFromText, storyCatalog, researchText: `${researchText}\n\n## Story catalog:\n${storyCatalog}` } }];

const input = $input.first()?.json || {};
const postType = input.postType || 'primary';
const pipelineSlot = input.pipelineSlot || 'publish';
const publishNow = input.publishNow === true;
if (input.topStories?.length) return [{ json: { ...input } }];
const TOPICS = ['Breaking Tech News','AI News','Software Engineering','System Design','Architecture','Cloud','Cybersecurity','Programming Languages','Developer Tools','Open Source','GitHub Trending','Tech Companies','Startups','Engineering Career','Debugging','Performance','DevOps','Databases','Frontend','Backend','Testing','Productivity','History of Computing','Engineering Opinion','Tool Spotlight','Weekly Roundup'];
const ENGAGE_TOPICS = ['Engineering Opinion','Productivity','Tool Spotlight','Testing','Debugging'];
const DEEP_TOPICS = ['System Design','Architecture','Backend','DevOps','Performance','Databases','Cloud'];
const pool = postType === 'engage' ? ENGAGE_TOPICS : postType === 'deep' ? DEEP_TOPICS : TOPICS;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.recentTopics)) staticData.recentTopics = [];
const recent = new Set(staticData.recentTopics.slice(-8));
let candidates = pool.filter((t) => !recent.has(t));
if (!candidates.length) candidates = [...pool];
const topic = candidates[Math.floor(Math.random() * candidates.length)];
staticData.recentTopics.push(topic);
if (staticData.recentTopics.length > 16) staticData.recentTopics = staticData.recentTopics.slice(-16);
return [{ json: { topic, postType, pipelineSlot, publishNow, skipResearch: postType === 'engage' || postType === 'deep', pickedAt: new Date().toISOString() } }];

function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

function parseWriterOutput(rawText) {
  const cleaned = rawText.replace(/^```json\s*|```\s*$/g, '').trim();
  try { return JSON.parse(cleaned); } catch { return null; }
}

function parseDraftObjects(rawText) {
  const cleaned = rawText.replace(/^```json\s*|```\s*$/g, '').trim();
  const parsed = parseWriterOutput(cleaned);
  if (parsed?.drafts?.length) return parsed.drafts;
  if (parsed?.headline || parsed?.message) return [parsed];
  return [];
}

const writer = safeNode('AI Writer') || {};
const context = safeNode('Collect and Score Sources') || safeNode('Topic') || safeNode('Format Research') || {};

let parsed = null;
if (writer.output && typeof writer.output === 'object') parsed = writer.output;
else if (writer.parsedOutput && typeof writer.parsedOutput === 'object') parsed = writer.parsedOutput;

let drafts = [];
if (parsed?.drafts?.length) drafts = parsed.drafts;
else if (parsed?.headline || parsed?.message) drafts = [parsed];
else {
  let text = '';
  if (Array.isArray(writer.content)) text = writer.content.find((c) => c.type === 'text')?.text || '';
  else if (typeof writer.text === 'string') text = writer.text;
  drafts = parseDraftObjects(text);
}

drafts = drafts.filter((d) => d.message || d.headline);

function draftScore(draft) {
  let score = Number(draft.score) || 0;
  const msg = draft.message || '';
  if (msg.includes('?')) score += 10;
  if (msg.length >= 200 && msg.length <= 1400) score += 8;
  if (draft.headline) score += 5;
  if (msg.startsWith('{')) score -= 50;
  return score;
}

drafts.sort((a, b) => draftScore(b) - draftScore(a));
const winner = drafts[0] || {
  headline: context.topic || 'Tech update',
  message: 'Unable to parse writer output.',
  short_message: 'Unable to parse writer output.',
  story_index: 1,
  score: 0,
};

return [{ json: {
  ...winner,
  draftsGenerated: drafts.length,
  topic: context.topic,
  postType: context.postType || 'primary',
  pipelineSlot: context.pipelineSlot || 'publish',
  publishNow: context.publishNow === true,
} }];

function safeNode(name) {
  try {
    return $(name).first()?.json || null;
  } catch {
    return null;
  }
}

const parsed = $input.first()?.json || safeNode('Parse Post JSON') || {};
const selected = safeNode('Select Best Draft') || {};
const today = new Date().toISOString().slice(0, 10);

const draft = {
  date: today,
  post_type: 'primary',
  headline: selected.headline || parsed.headline || '',
  message: selected.message || parsed.message || '',
  short_message: selected.short_message || parsed.short_message || '',
  primary_url: parsed.primaryUrl || '',
  topic: selected.topic || parsed.topic || '',
  story_index: selected.story_index || parsed.story_index || 1,
  story_title: parsed.story_title || '',
  saved_at: new Date().toISOString(),
  draftsGenerated: selected.draftsGenerated || 1,
};

if (!draft.message || draft.message.trim().startsWith('{')) {
  throw new Error('Draft message is empty or still raw JSON. Re-run 7AM Prep.');
}

return [{ json: { status: 'saved', date: today, draft, message: `Primary draft saved for ${today}. Ready for 8:00 AM publish.` } }];

function safeAll(name) {
  try { return $(name).all().map((item) => item.json); } catch { return []; }
}

const today = new Date().toISOString().slice(0, 10);
const slot = $('Init Primary Slot').first()?.json || { pipelineSlot: 'publish', postType: 'primary', publishNow: false };
const rows = safeAll("Get Today's Draft");
const row = rows.find((r) => r.date === today && r.message && !String(r.message).trim().startsWith('{'));

if (row?.message) {
  return [{ json: {
    hasDraft: true,
    headline: row.headline,
    message: row.message,
    short_message: row.short_message,
    primaryUrl: row.primary_url,
    topic: row.topic,
    story_index: row.story_index,
    story_title: row.story_title,
    saved_at: row.saved_at,
    date: row.date,
    pipelineSlot: 'publish',
    postType: 'primary',
    publishNow: slot.publishNow === true,
    loadedFrom: `data-table (${today})`,
  } }];
}

return [{ json: {
  hasDraft: false,
  pipelineSlot: slot.pipelineSlot || 'publish',
  postType: slot.postType || 'primary',
  publishNow: slot.publishNow === true,
  generateFallback: true,
  draftMissing: true,
  message: `No saved draft for ${today}. Generating content inline before saving to Postiz as draft.`,
} }];

function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

const slot = safeNode('Init Primary Slot') || safeNode('Init Prep Slot') || $input.first()?.json || {};
const pipelineSlot = slot.pipelineSlot || 'prep';
const postType = slot.postType || 'primary';
const publishNow = slot.publishNow === true;

const UA = 'Mozilla/5.0 (compatible; IntraWebSocialBot/1.0; +https://intrawebtech.com)';
const SOURCE_WEIGHTS = { 'hacker-news': 10, 'github-trending': 9, 'product-hunt': 8, reddit: 7 };
const KEYWORDS = ['ai', 'software', 'engineering', 'developer', 'cloud', 'security', 'database', 'frontend', 'backend', 'devops', 'open source', 'startup', 'architecture', 'programming', 'api', 'kubernetes', 'typescript', 'python', 'react', 'llm'];

async function fetchText(url) {
  try {
    const body = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'User-Agent': UA, Accept: 'application/rss+xml, application/xml, text/xml, */*' }, timeout: 30000 });
    const text = typeof body === 'string' ? body : JSON.stringify(body);
    if (/502 Bad Gateway|<title>502/i.test(text)) return '';
    return text;
  } catch { return ''; }
}

async function fetchHnStories() {
  for (const url of ['https://news.ycombinator.com/rss', 'https://hnrss.org/best?count=30']) {
    const xml = await fetchText.call(this, url);
    if (xml && /<item/i.test(xml)) return { xml, status: 'ok', via: url };
  }
  try {
    const ids = await this.helpers.httpRequest({ method: 'GET', url: 'https://hacker-news.firebaseio.com/v0/topstories.json', json: true, timeout: 30000 });
    const stories = [];
    for (const id of (ids || []).slice(0, 20)) {
      try {
        const item = await this.helpers.httpRequest({ method: 'GET', url: `https://hacker-news.firebaseio.com/v0/item/${id}.json`, json: true, timeout: 15000 });
        if (item?.title && item?.url) stories.push({ title: item.title, link: item.url, summary: '', source: 'hacker-news', publishedAt: new Date((item.time || Date.now() / 1000) * 1000).toISOString() });
      } catch {}
    }
    if (stories.length) return { stories, status: 'ok', via: 'firebase-api' };
  } catch {}
  return { xml: '', stories: [], status: 'failed', via: 'none' };
}

function parseRss(xml, source) {
  if (!xml || typeof xml !== 'string') return [];
  const blocks = xml.match(/<(?:item|entry)[\s\S]*?<\/(?:item|entry)>/gi) || [];
  const stories = [];
  for (const block of blocks) {
    const titleMatch = block.match(/<title[^>]*>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/i);
    const linkMatch = block.match(/<link[^>]*href="([^"]+)"/i) || block.match(/<link[^>]*>([\s\S]*?)<\/link>/i);
    const descMatch = block.match(/<(?:description|summary|content)[^>]*>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/(?:description|summary|content)>/i);
    const dateMatch = block.match(/<(?:pubDate|updated|published)[^>]*>([\s\S]*?)<\/(?:pubDate|updated|published)>/i);
    const title = (titleMatch?.[1] || '').replace(/<[^>]*>/g, '').trim();
    const link = (linkMatch?.[1] || '').replace(/<[^>]*>/g, '').trim();
    const summary = (descMatch?.[1] || '').replace(/<[^>]*>/g, '').trim().slice(0, 400);
    const publishedAt = dateMatch ? new Date(dateMatch[1].trim()) : new Date();
    if (!title || !link || !/^https?:\/\//i.test(link)) continue;
    stories.push({ title, link, summary, source, publishedAt: publishedAt.toISOString() });
  }
  return stories;
}

const fetchStatus = {};
const all = [];
const hn = await fetchHnStories.call(this);
fetchStatus['hacker-news'] = hn.status;
if (hn.stories?.length) all.push(...hn.stories); else all.push(...parseRss(hn.xml, 'hacker-news'));
for (const [key, url] of [['github-trending', 'https://mshibanami.github.io/GitHubTrendingRSS/daily/all.xml'], ['reddit', 'https://www.reddit.com/r/programming+devops+technology/hot/.rss?limit=25'], ['product-hunt', 'https://www.producthunt.com/feed']]) {
  const xml = await fetchText.call(this, url);
  fetchStatus[key] = xml ? 'ok' : 'failed';
  all.push(...parseRss(xml, key));
}
const seen = new Set();
const now = Date.now();
function normalizeTitle(title) { return title.toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim(); }
function scoreStory(story) {
  let score = SOURCE_WEIGHTS[story.source] || 5;
  const ageHours = (now - new Date(story.publishedAt).getTime()) / 3600000;
  if (ageHours <= 24) score += 8; else if (ageHours <= 48) score += 4; else if (ageHours <= 72) score += 1;
  const haystack = `${story.title} ${story.summary}`.toLowerCase();
  for (const keyword of KEYWORDS) if (haystack.includes(keyword)) score += 1.5;
  try { if (new URL(story.link).pathname.split('/').filter(Boolean).length >= 2) score += 2; } catch {}
  return Math.round(score * 10) / 10;
}
const scored = [];
for (const story of all) {
  const key = `${normalizeTitle(story.title)}|${story.link}`;
  if (seen.has(key)) continue;
  seen.add(key);
  scored.push({ ...story, score: scoreStory(story) });
}
scored.sort((a, b) => b.score - a.score);
const topStories = scored.slice(0, 12);
if (!topStories.length) throw new Error(`All source fetches failed. Status: ${JSON.stringify(fetchStatus)}`);
return [{ json: { pipelineSlot, postType, publishNow, topic: topStories[0].title, topStories, storyCount: topStories.length, fetchStatus, collectedAt: new Date().toISOString(), generateFallback: slot.generateFallback === true } }];

const input = $input.first()?.json || {};
const today = new Date().toISOString().slice(0, 10);
if (!input.hasDraft) return [{ json: input }];
if (!input.message || String(input.message).trim().startsWith('{')) {
  throw new Error('Saved draft has invalid message. Re-run 7AM Prep.');
}
const savedMs = Date.parse(input.saved_at || '') || 0;
const ageHours = savedMs ? (Date.now() - savedMs) / 3600000 : 999;
const isToday = input.date === today || String(input.loadedFrom || '').includes(today);
if (!isToday || ageHours > 24) {
  return [{ json: {
    ...input,
    hasDraft: false,
    generateFallback: true,
    draftStale: true,
    message: `Draft is stale or missing for ${today}. Regenerating inline.`,
  } }];
}
return [{ json: { ...input, draftValid: true } }];

const input = $input.first()?.json || {};
const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const runningSince = staticData.runningSince || 0;
if (runningSince && (now - runningSince) < 30 * 60 * 1000) {
  return [{ json: { ...input, mutexBlocked: true, runningSince, slotStartedAt: now } }];
}
staticData.runningSince = now;
staticData.runStartedAt = now;
return [{ json: { ...input, mutexBlocked: false, runningSince: now, slotStartedAt: now } }];

const input = $input.first()?.json || {};
return [{ json: {
  execution_id: $execution.id,
  slot: input.pipelineSlot || 'unknown',
  post_type: input.postType || 'unknown',
  status: 'skipped',
  headline: '',
  topic: '',
  postiz_id: '',
  error_message: 'Mutex blocked — another run in progress',
  duration_ms: 0,
  created_at: new Date().toISOString(),
} }];

function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

const staticData = $getWorkflowStaticData('global');
const startedAt = staticData.runStartedAt || Date.now();
const post = safeNode('Parse Post JSON') || safeNode('Load Primary Draft') || safeNode('Validate Draft') || {};
const slot = safeNode('Acquire Mutex') || {};
const postiz = safeNode('Postiz - Post All Channels') || {};
const uploadFailed = safeNode('Mark Upload Failed');

let status = 'success';
let errorMessage = '';
if (uploadFailed?.mediaUploadFailed) {
  status = 'partial';
  errorMessage = uploadFailed.uploadError || 'Postiz media upload failed; posted text-only';
}
if (postiz.error) {
  status = 'error';
  errorMessage = postiz.error.message || JSON.stringify(postiz.error).slice(0, 500);
}

return [{ json: {
  execution_id: $execution.id,
  slot: slot.pipelineSlot || post.pipelineSlot || 'unknown',
  post_type: post.postType || slot.postType || 'primary',
  status,
  headline: post.headline || '',
  topic: post.topic || '',
  postiz_id: String(postiz.id || postiz.postId || postiz.data?.id || ''),
  error_message: errorMessage,
  duration_ms: Date.now() - startedAt,
  created_at: new Date().toISOString(),
} }];

const post = $('Parse Post JSON').first()?.json || $('Load Primary Draft').first()?.json || $('Validate Draft').first()?.json || $input.first()?.json || {};
const err = $input.first()?.json?.error || {};
return [{ json: {
  ...post,
  mediaUploadFailed: true,
  uploadError: err.message || err.description || 'Postiz upload failed',
} }];

